/** A page body: `count` rows, claiming `pages` pages in all. */
function page(n: number, pages: number, count = 2) {
  return {
    data: Array.from({ length: count }, (_, i) => ({ id: n * 100 + i })),
    pagination: {
      current_page: n,
      per_page: 100,
      total_entries: pages * count,
      total_pages: pages,
    },
  };
}

Deno.test({
  name: "dnsimpleApiPaginated: walks every page and merges the results",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi(
      (req) => ({ body: page(Number(req.url.searchParams.get("page")), 3) }),
      async (requests) => {
        const out = await dnsimpleApiPaginated<{ id: number }>(
          ARGS,
          "/1010/zones",
          { query: { name_like: "ex" } },
        );
        assertEquals(out.results.length, 6);
        assertEquals(out.truncated, false);
        assertEquals(out.totalEntries, 6);
        assertEquals(
          requests.map((r) => r.url.searchParams.get("page")),
          ["1", "2", "3"],
        );
        assertEquals(
          requests.every((r) =>
            r.url.searchParams.get("per_page") === "100" &&
            r.url.searchParams.get("name_like") === "ex"
          ),
          true,
        );
      },
    );
  },
});

